import * as React from "react";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

const buttonVariants = cva(
  // Base — matches Flutter's ElevatedButton shape and font
  "inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-md text-sm font-medium transition-all duration-200 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 ring-offset-background disabled:pointer-events-none disabled:opacity-50 [&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
  {
    variants: {
      variant: {
        // Primary — #1565C0 bg, white text (matches Flutter ElevatedButton light)
        default:
          "bg-primary text-white shadow-sm hover:bg-primary-light active:scale-[0.97]",
        // Destructive — error red
        destructive:
          "bg-error text-white shadow-sm hover:bg-error/90 active:scale-[0.97]",
        // Outline — transparent with primary border (matches Flutter OutlinedButton)
        outline:
          "border border-primary bg-transparent text-primary hover:bg-primary hover:text-white active:scale-[0.97]",
        // Secondary — surface bg with text-primary
        secondary:
          "bg-surface text-text-primary border border-divider shadow-sm hover:bg-muted active:scale-[0.97]",
        // Ghost — no bg, text-secondary on hover
        ghost:
          "hover:bg-surface hover:text-primary text-text-secondary",
        // Link
        link:
          "text-primary underline-offset-4 hover:underline",
      },
      size: {
        default: "h-11 px-6 py-3.5",        // matches Flutter vertical:14, horizontal:24
        sm: "h-9 rounded-md px-3 text-sm",
        lg: "h-12 rounded-lg px-8 text-base",
        icon: "h-10 w-10",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
);

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
  VariantProps<typeof buttonVariants> {
  asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
  ({ className, variant, size, asChild = false, ...props }, ref) => {
    const Comp = asChild ? Slot : "button";
    return (
      <Comp
        className={cn(buttonVariants({ variant, size, className }))}
        ref={ref}
        {...props}
      />
    );
  }
);
Button.displayName = "Button";

export { Button, buttonVariants };
